from pathlib import Path
import json

root = Path(__file__).resolve().parent.parent

def read(path):
    return (root / path).read_text()

def write(path, content):
    target = root / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one anchor, found {count}")
    return text.replace(old, new, 1)

write('src/presentation/theme.ts', 'export const INTERFACE_THEME_KEY = "galileo-gallery-interface-theme-v1"\nexport const INTERFACE_THEME_EVENT = "galileo-gallery:interface-theme-change"\n\nexport type InterfaceTheme = "light" | "dark"\nexport type InterfaceThemeSource = "system" | "user" | "export-neutral"\n\nconst THEME_COLOURS: Record<InterfaceTheme, string> = {\n    light: "#f3f0e9",\n    dark: "#151613",\n}\n\nfunction isInterfaceTheme(value: unknown): value is InterfaceTheme {\n    return value === "light" || value === "dark"\n}\n\nfunction systemInterfaceTheme(): InterfaceTheme {\n    return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"\n}\n\nfunction readStoredInterfaceTheme(): InterfaceTheme | null {\n    try {\n        const stored = window.localStorage.getItem(INTERFACE_THEME_KEY)\n        return isInterfaceTheme(stored) ? stored : null\n    } catch {\n        return null\n    }\n}\n\nfunction updateThemeColour(theme: InterfaceTheme) {\n    document.querySelector<HTMLMetaElement>(\'meta[name="theme-color"]\')?.setAttribute("content", THEME_COLOURS[theme])\n}\n\nfunction applyInterfaceTheme(theme: InterfaceTheme, source: InterfaceThemeSource) {\n    const root = document.documentElement\n    const changed = root.dataset.theme !== theme || root.dataset.themeSource !== source\n    root.dataset.theme = theme\n    root.dataset.themeSource = source\n    root.style.colorScheme = theme\n    updateThemeColour(theme)\n    if (changed) {\n        window.dispatchEvent(new CustomEvent(INTERFACE_THEME_EVENT, {\n            detail: { theme, source },\n        }))\n    }\n    return theme\n}\n\nexport function getInterfaceTheme(): InterfaceTheme {\n    const current = document.documentElement.dataset.theme\n    return isInterfaceTheme(current) ? current : systemInterfaceTheme()\n}\n\nexport function setInterfaceTheme(theme: InterfaceTheme) {\n    try {\n        window.localStorage.setItem(INTERFACE_THEME_KEY, theme)\n    } catch {\n        // The visible preference still applies for this window.\n    }\n    return applyInterfaceTheme(theme, "user")\n}\n\nexport function toggleInterfaceTheme() {\n    return setInterfaceTheme(getInterfaceTheme() === "dark" ? "light" : "dark")\n}\n\nexport function subscribeInterfaceTheme(listener: () => void) {\n    window.addEventListener(INTERFACE_THEME_EVENT, listener)\n    return () => window.removeEventListener(INTERFACE_THEME_EVENT, listener)\n}\n\nexport function initializeInterfaceTheme() {\n    const root = document.documentElement\n    if (root.dataset.themeInitialized === "true") return () => {}\n\n    const exportView = new URLSearchParams(window.location.search).has("export")\n    if (exportView) {\n        applyInterfaceTheme("light", "export-neutral")\n        root.dataset.themeInitialized = "true"\n        return () => {}\n    }\n\n    const media = window.matchMedia("(prefers-color-scheme: dark)")\n    const stored = readStoredInterfaceTheme()\n    applyInterfaceTheme(stored ?? (media.matches ? "dark" : "light"), stored ? "user" : "system")\n    root.dataset.themeInitialized = "true"\n\n    const onSystemChange = () => {\n        if (readStoredInterfaceTheme()) return\n        applyInterfaceTheme(media.matches ? "dark" : "light", "system")\n    }\n    const onStorage = (event: StorageEvent) => {\n        if (event.key !== INTERFACE_THEME_KEY) return\n        const next = isInterfaceTheme(event.newValue) ? event.newValue : null\n        applyInterfaceTheme(next ?? (media.matches ? "dark" : "light"), next ? "user" : "system")\n    }\n\n    media.addEventListener("change", onSystemChange)\n    window.addEventListener("storage", onStorage)\n    return () => {\n        media.removeEventListener("change", onSystemChange)\n        window.removeEventListener("storage", onStorage)\n    }\n}\n')
write('src/presentation/ThemeControl.tsx', 'import * as React from "react"\nimport Icon from "../ui/PhosphorIcon"\nimport {\n    getInterfaceTheme,\n    setInterfaceTheme,\n    subscribeInterfaceTheme,\n} from "./theme"\n\nexport default function ThemeControl() {\n    const theme = React.useSyncExternalStore(\n        subscribeInterfaceTheme,\n        getInterfaceTheme,\n        getInterfaceTheme\n    )\n    const next = theme === "dark" ? "light" : "dark"\n    const label = `Switch to ${next} mode`\n\n    return (\n        <button\n            className="icon-button theme-control"\n            type="button"\n            data-interface-theme-control\n            data-interface-theme={theme}\n            aria-label={label}\n            aria-pressed={theme === "dark"}\n            title={label}\n            onClick={() => setInterfaceTheme(next)}\n        >\n            <Icon name={next === "dark" ? "moon" : "sun"} size={21} weight="bold" />\n        </button>\n    )\n}\n')
write('src/themeModes.css', '/* Interface colour modes. Scene renderers, media, Project data, and export canvases stay outside this layer. */\n:root,\n:root[data-theme="light"] {\n    color-scheme: light;\n    --ink: #181917;\n    --muted: #62665f;\n    --hairline: rgba(24, 25, 23, .18);\n    --material: #fbfaf6;\n    --accent: #f15f48;\n    --accent-bright: #ff8069;\n    --accent-soft: #ffd1c8;\n    --paper: #f3f0e9;\n    --paper-raised: #fffefb;\n    --paper-cool: #d8e8f7;\n    --workspace: #20211f;\n    --hard-shadow: 6px 6px 0 #181917;\n\n    --ui-titlebar: rgba(251, 250, 246, .96);\n    --ui-control-fg: #434640;\n    --ui-control-muted: #70736d;\n    --ui-control-hover: rgba(24, 25, 23, .085);\n    --ui-subtle-bg: rgba(24, 25, 23, .03);\n    --ui-subtle-bg-strong: rgba(24, 25, 23, .06);\n    --ui-subtle-border: rgba(24, 25, 23, .38);\n    --ui-popover: rgba(255, 254, 251, .985);\n    --ui-popover-shadow: 0 24px 64px rgba(24, 25, 23, .20), 0 0 0 1px rgba(24, 25, 23, .14);\n    --ui-media-actions: #f7f6f1;\n    --ui-gallery-tools: rgba(244, 242, 236, .94);\n    --ui-gallery-card: rgba(255, 254, 251, .90);\n    --ui-gallery-current: #f7a18f;\n    --ui-workspace-grid: rgba(255, 255, 255, .035);\n    --ui-on-workspace: rgba(255, 255, 255, .72);\n    --ui-on-workspace-strong: #f5f3ed;\n    --ui-workspace-outline: rgba(255, 255, 255, .82);\n    --ui-workspace-shadow: rgba(0, 0, 0, .42);\n    --ui-tooltip: rgba(35, 36, 33, .97);\n    --ui-tooltip-text: rgba(255, 255, 255, .90);\n    --ui-positive: #3f9b69;\n    --ui-danger: #b93431;\n    --ui-danger-soft: rgba(203, 68, 61, .08);\n    --ui-accent-text: #a34b3b;\n    --ui-on-accent: #181917;\n    --ui-action-bg: #181917;\n    --ui-action-fg: #ffffff;\n    --ui-focus-mix: white;\n    --ui-scrollbar: rgba(24, 25, 23, .20);\n    --ui-stage-scrollbar: rgba(255, 255, 255, .20);\n    --pd-select-caret: url("./assets/icons/caret-down.svg");\n}\n\n:root[data-theme="dark"] {\n    color-scheme: dark;\n    --ink: #f5f1e8;\n    --muted: #afb2aa;\n    --hairline: rgba(245, 241, 232, .18);\n    --material: #1b1c19;\n    --accent: #ff765f;\n    --accent-bright: #ff9c84;\n    --accent-soft: #4b2923;\n    --paper: #151613;\n    --paper-raised: #232420;\n    --paper-cool: #222b31;\n    --workspace: #0c0d0c;\n    --hard-shadow: 6px 6px 0 #080908;\n\n    --ui-titlebar: rgba(21, 22, 19, .96);\n    --ui-control-fg: #d8d9d2;\n    --ui-control-muted: #a5a8a1;\n    --ui-control-hover: rgba(245, 241, 232, .10);\n    --ui-subtle-bg: rgba(245, 241, 232, .045);\n    --ui-subtle-bg-strong: rgba(245, 241, 232, .08);\n    --ui-subtle-border: rgba(245, 241, 232, .34);\n    --ui-popover: rgba(37, 38, 34, .985);\n    --ui-popover-shadow: 0 28px 72px rgba(0, 0, 0, .50), 0 0 0 1px rgba(245, 241, 232, .15);\n    --ui-media-actions: #20211e;\n    --ui-gallery-tools: rgba(27, 28, 25, .95);\n    --ui-gallery-card: rgba(35, 36, 32, .94);\n    --ui-gallery-current: #5a3028;\n    --ui-workspace-grid: rgba(255, 255, 255, .026);\n    --ui-on-workspace: rgba(245, 241, 232, .72);\n    --ui-on-workspace-strong: #f5f1e8;\n    --ui-workspace-outline: rgba(245, 241, 232, .72);\n    --ui-workspace-shadow: rgba(0, 0, 0, .68);\n    --ui-tooltip: rgba(8, 9, 8, .98);\n    --ui-tooltip-text: rgba(245, 241, 232, .94);\n    --ui-positive: #70ca8c;\n    --ui-danger: #ff8b82;\n    --ui-danger-soft: rgba(255, 139, 130, .10);\n    --ui-accent-text: #ff9a85;\n    --ui-on-accent: #20110e;\n    --ui-action-bg: #f5f1e8;\n    --ui-action-fg: #151613;\n    --ui-focus-mix: black;\n    --ui-scrollbar: rgba(245, 241, 232, .22);\n    --ui-stage-scrollbar: rgba(245, 241, 232, .20);\n    --pd-select-caret: url("./assets/icons/caret-down-dark.svg");\n}\n\nhtml,\nbody,\n#root {\n    color: var(--ink);\n    background: var(--workspace);\n}\n\n.interface-scale-viewport { background: var(--workspace); }\n\n.app-shell,\n.style-gallery-shell,\n.titlebar,\n.panel-material,\n.interface-scale-control,\n.button,\n.icon-button,\n.add-media,\n.inspector-top,\n.segment,\n.project-menu-panel,\n.style-gallery-tools,\n.style-card,\ninput,\nselect,\ntextarea {\n    transition:\n        color 180ms var(--pd-motion-ease, ease),\n        background-color 180ms var(--pd-motion-ease, ease),\n        border-color 180ms var(--pd-motion-ease, ease),\n        box-shadow 180ms var(--pd-motion-ease, ease);\n}\n\n.app-shell {\n    color: var(--ink);\n    background: var(--paper);\n}\n\n.titlebar {\n    color: var(--ink);\n    background: var(--ui-titlebar);\n}\n\n.brand-lockup span,\n.autosave-status,\n.style-gallery-header p,\n.style-card small,\n.style-gallery-footer,\n.preset-note,\n.expert-help,\n.privacy-note,\n.export-summary span,\n.project-menu-panel small {\n    color: var(--muted);\n}\n\n.autosave-status { color: color-mix(in srgb, var(--ink) 52%, transparent); }\n.autosave-status i { background: var(--ui-positive); }\n\n.interface-scale-control,\n.button,\n.icon-button,\n.project-trigger {\n    border-color: var(--ink);\n    color: var(--ink);\n    background: var(--paper-raised);\n}\n\n.button.quiet,\n.icon-button,\n.add-media { color: var(--ui-control-fg); }\n\n.theme-control {\n    position: relative;\n    flex: 0 0 auto;\n    min-width: var(--pd-control-default);\n    min-height: var(--pd-control-default);\n    overflow: hidden;\n    -webkit-app-region: no-drag;\n}\n\n.theme-control > svg {\n    width: 21px;\n    height: 21px;\n    transition: transform 220ms var(--pd-motion-ease, ease), opacity 180ms ease;\n}\n\n.theme-control:active > svg { transform: rotate(-12deg) scale(.94); }\n\n.button.primary {\n    border-color: var(--ink);\n    color: var(--ui-on-accent);\n    background: var(--accent);\n    box-shadow: 4px 4px 0 var(--ink);\n}\n\n.project-menu > .project-menu-panel {\n    border-color: var(--ink);\n    color: var(--ink);\n    background: var(--ui-popover);\n    box-shadow: var(--ui-popover-shadow);\n}\n\n.project-menu-panel button { color: var(--ui-control-fg); }\n.project-menu-divider { background: var(--hairline); }\n\n.panel-material { background: var(--material); }\n.library,\n.inspector,\n.inspector-top,\n.control-section,\n.motion-workspace-intro,\n.style-gallery-tools { border-color: var(--ink); }\n\n.eyebrow,\n.field-label,\n.playback-direction > span,\n.expert-field > span,\n.number-pair label > span,\n.color-row > span,\n.range-row > span { color: color-mix(in srgb, var(--ink) 72%, var(--muted)); }\n\n.library-scroll,\n.inspector-scroll,\n.style-gallery-shell { scrollbar-color: var(--ui-scrollbar) transparent; }\n\n.empty-library,\n.style-current-panel,\n.scene-preset-select select,\n.compact-controls select,\n.expert-field select,\n.expert-field input[type="text"],\n.selected-media-card select,\n.number-pair input,\n.canvas-dimensions input,\n.range-value,\n.export-summary div,\n.export-progress,\n.toggle-row > i {\n    color: var(--ink);\n    background: var(--paper-raised);\n}\n\n.empty-library {\n    border-color: var(--ui-subtle-border);\n}\n\n.empty-orbit {\n    border-color: var(--ink);\n    color: var(--ui-on-accent);\n    background: var(--accent);\n}\n\n.media-row,\n.motion-grid button,\n.canvas-preset-grid button,\n.background-style-grid button,\n.format-cards button,\n.expert-presets button,\n.expert-tabs button,\n.poster-choice button,\n.color-row button {\n    color: var(--ui-control-muted);\n    background: var(--ui-subtle-bg);\n    border-color: color-mix(in srgb, var(--ink) 72%, transparent);\n}\n\n.media-row.is-selected,\n.motion-grid button.is-active,\n.canvas-preset-grid button.is-active,\n.background-style-grid button.is-active,\n.poster-choice button.is-active,\n.expert-tabs button.is-active,\n.segment button.is-active {\n    border-color: var(--ink);\n    color: var(--ink);\n    background: var(--accent-soft);\n}\n\n.media-copy strong,\n.toggle-row strong,\n.expert-empty strong,\n.export-success strong { color: var(--ink); }\n\n.drag-handle { color: color-mix(in srgb, var(--ink) 32%, transparent); }\n.media-actions { background: var(--ui-media-actions); }\n.media-actions button { color: var(--ui-control-muted); }\n.media-actions button.is-active,\n.finale-pill,\n.profile-guidance,\n.style-card p em { color: var(--ui-accent-text) !important; }\n.media-actions button.danger,\n.expert-error,\n.export-error { color: var(--ui-danger); }\n\n.add-media {\n    border-color: var(--ink);\n    background: var(--paper-cool);\n}\n\n.tooltip-bubble {\n    border-color: color-mix(in srgb, var(--ui-tooltip-text) 14%, transparent);\n    color: var(--ui-tooltip-text);\n    background: var(--ui-tooltip);\n}\n\n.studio {\n    background:\n        linear-gradient(var(--ui-workspace-grid) 1px, transparent 1px),\n        linear-gradient(90deg, var(--ui-workspace-grid) 1px, transparent 1px),\n        var(--workspace);\n    scrollbar-color: var(--ui-stage-scrollbar) transparent;\n}\n\n.stage-meta,\n.transport time,\n.studio-note { color: var(--ui-on-workspace); }\n\n.stage-shell {\n    outline-color: var(--ui-workspace-outline);\n    box-shadow: 14px 14px 0 var(--ui-workspace-shadow);\n}\n\n.transport-play {\n    border-color: var(--ui-workspace-outline);\n    color: var(--ui-on-workspace-strong);\n    background: color-mix(in srgb, var(--ui-on-workspace-strong) 4%, transparent);\n}\n\n.timeline::-webkit-slider-thumb {\n    border-color: var(--workspace);\n    background: var(--ui-on-workspace-strong);\n}\n\n.inspector-top,\n.expert-tabs { background: var(--paper-cool); }\n\n.segment { border-color: var(--ink); background: var(--paper-raised); }\n.segment button { color: var(--ui-control-muted); }\n.segment button.is-active { background: var(--accent); }\n\n.style-current-panel {\n    border-color: var(--ink);\n    background: var(--accent-soft);\n    box-shadow: var(--hard-shadow);\n}\n\nselect:not([multiple]) {\n    color: var(--ink);\n    background-color: var(--paper-raised);\n    background-image: var(--pd-select-caret) !important;\n}\n\noption {\n    color: var(--ink);\n    background: var(--paper-raised);\n}\n\ninput,\ntextarea {\n    color: var(--ink);\n    background-color: var(--paper-raised);\n    border-color: var(--hairline);\n}\n\ninput::placeholder,\ntextarea::placeholder { color: color-mix(in srgb, var(--muted) 78%, transparent); }\n\n.range-row input[type="range"]::-webkit-slider-runnable-track {\n    background: linear-gradient(90deg, var(--accent) var(--range-progress), color-mix(in srgb, var(--ink) 14%, transparent) var(--range-progress));\n}\n\n.range-row input[type="range"]::-webkit-slider-thumb {\n    border-color: var(--paper-raised);\n    background: var(--ink);\n    box-shadow: 0 2px 7px color-mix(in srgb, var(--ink) 24%, transparent);\n}\n\n.toggle-row > i { border-color: var(--ink); }\n.toggle-row > i::after { background: var(--ink); }\n.toggle-row input:checked + i { background: var(--accent); }\n.toggle-row input:checked + i::after { background: var(--ui-on-accent); }\n\n.format-cards button.is-active {\n    border-color: var(--ink);\n    background: var(--accent-soft);\n}\n.format-cards button svg,\n.export-mark { color: var(--accent); }\n.export-mark { background: var(--paper-cool); border-color: var(--hairline); }\n\n.export-summary,\n.export-progress { border-color: var(--ink); }\n.export-button {\n    border-color: var(--ink);\n    color: var(--ui-action-fg);\n    background: var(--ui-action-bg);\n    box-shadow: 5px 5px 0 var(--accent);\n}\n\n.export-success button {\n    color: var(--ink);\n    background: var(--ui-subtle-bg-strong);\n}\n.export-error { background: var(--ui-danger-soft); }\n\n.launch-screen {\n    color: var(--ink);\n    background: var(--paper-cool);\n}\n.launch-frame { border-color: var(--hairline); background: var(--paper-raised); }\n.launch-progress { background: color-mix(in srgb, var(--ink) 14%, transparent); }\n.launch-progress span { background: var(--accent); }\n\n.style-gallery-shell {\n    color: var(--ink);\n    background:\n        linear-gradient(color-mix(in srgb, var(--ink) 3.2%, transparent) 1px, transparent 1px),\n        linear-gradient(90deg, color-mix(in srgb, var(--ink) 3.2%, transparent) 1px, transparent 1px),\n        var(--paper);\n}\n\n.style-gallery-header .galileo-app-icon { border-color: var(--ink); }\n.style-gallery-tools { background: var(--ui-gallery-tools); }\n.style-category-pills button { color: var(--ui-control-muted); }\n.style-category-pills button.is-active {\n    border-color: var(--ink);\n    color: var(--ui-action-fg);\n    background: var(--ui-action-bg);\n}\n.style-search { color: var(--muted); }\n.style-search input {\n    border-color: var(--ink);\n    color: var(--ink);\n    background: var(--paper-raised);\n}\n\n.style-card {\n    border-color: var(--ink);\n    color: var(--ink);\n    background: var(--ui-gallery-card);\n    box-shadow: 8px 8px 0 color-mix(in srgb, var(--ink) 14%, transparent);\n}\n.style-card.is-current {\n    border-color: var(--ink);\n    background: var(--ui-gallery-current);\n    box-shadow: 8px 8px 0 var(--ink);\n}\n.style-card strong,\n.style-gallery-empty strong { color: var(--ink); }\n.style-card p,\n.style-gallery-empty { color: var(--muted); }\n.style-miniature { border-color: var(--ink); }\n\nbutton:focus-visible,\ninput:focus-visible,\nselect:focus-visible,\ntextarea:focus-visible,\nsummary:focus-visible {\n    outline-color: color-mix(in srgb, var(--accent) 78%, var(--ui-focus-mix));\n}\n\n@container (max-width: 1360px) and (min-width: 921px) {\n    .title-actions { gap: var(--pd-space-2); }\n    .title-actions > .button { padding-inline: var(--pd-space-3); }\n    .autosave-status { max-width: 132px; }\n}\n\n@media (hover: hover) and (pointer: fine) {\n    .interface-scale-control button:not(:disabled):hover,\n    .button.quiet:hover,\n    .icon-button:hover,\n    .add-media:hover,\n    .theme-control:hover {\n        color: var(--ink);\n        background: var(--ui-control-hover);\n    }\n\n    .button.primary:hover {\n        color: var(--ui-on-accent);\n        background: var(--accent-bright);\n        box-shadow: 4px 4px 0 var(--ink);\n    }\n\n    .project-menu-panel button:hover,\n    .media-actions button:hover,\n    .expert-presets button:hover {\n        color: var(--ink);\n        background: var(--ui-subtle-bg-strong);\n    }\n\n    .media-row:hover { border-color: var(--ui-subtle-border); background: var(--ui-subtle-bg); }\n    .media-row.is-selected:hover { border-color: var(--ink); background: var(--accent-soft); }\n    .style-card:hover {\n        border-color: var(--ink);\n        background: var(--paper-raised);\n        box-shadow: 12px 12px 0 color-mix(in srgb, var(--ink) 18%, transparent);\n    }\n    .style-card.is-current:hover { background: var(--ui-gallery-current); box-shadow: 12px 12px 0 var(--ink); }\n}\n\n@media (hover: none), (pointer: coarse) {\n    .project-menu-panel button:hover,\n    .media-actions button:hover,\n    .expert-presets button:hover { color: var(--ui-control-fg); background: transparent; }\n    .media-row:hover { border-color: transparent; background: var(--ui-subtle-bg); }\n    .media-row.is-selected:hover { border-color: var(--ink); background: var(--accent-soft); }\n    .add-media:hover { color: var(--ui-control-fg); background: var(--paper-cool); }\n    .style-card:hover { transform: none; border-color: var(--ink); background: var(--ui-gallery-card); box-shadow: 8px 8px 0 color-mix(in srgb, var(--ink) 14%, transparent); }\n    .style-card.is-current:hover { background: var(--ui-gallery-current); box-shadow: 8px 8px 0 var(--ink); }\n}\n\n@media (prefers-reduced-transparency: reduce) {\n    .titlebar,\n    .panel-material,\n    .style-gallery-tools,\n    .project-menu-panel {\n        backdrop-filter: none;\n        background: var(--paper-raised);\n    }\n}\n\n@media (prefers-contrast: more) {\n    :root,\n    :root[data-theme="light"] {\n        --muted: #454842;\n        --hairline: rgba(24, 25, 23, .36);\n        --ui-subtle-border: rgba(24, 25, 23, .62);\n    }\n\n    :root[data-theme="dark"] {\n        --muted: #d4d5cf;\n        --hairline: rgba(245, 241, 232, .40);\n        --ui-subtle-border: rgba(245, 241, 232, .64);\n    }\n}\n\n@media (forced-colors: active) {\n    .theme-control,\n    .interface-scale-control,\n    .button,\n    .icon-button,\n    .add-media,\n    .project-menu-panel,\n    .style-card,\n    input,\n    select,\n    textarea {\n        forced-color-adjust: auto;\n    }\n\n    .studio { background: Canvas; }\n    .stage-shell { outline-color: CanvasText; box-shadow: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .app-shell,\n    .style-gallery-shell,\n    .titlebar,\n    .panel-material,\n    .interface-scale-control,\n    .button,\n    .icon-button,\n    .add-media,\n    .inspector-top,\n    .segment,\n    .project-menu-panel,\n    .style-gallery-tools,\n    .style-card,\n    input,\n    select,\n    textarea,\n    .theme-control > svg {\n        transition-duration: 0ms;\n        transition-delay: 0ms;\n    }\n}\n')
write('public/theme-preflight.js', '(() => {\n    const key = "galileo-gallery-interface-theme-v1"\n    const root = document.documentElement\n    const exportView = new URLSearchParams(window.location.search).has("export")\n    let theme = "light"\n    let source = "export-neutral"\n\n    if (!exportView) {\n        let stored = null\n        try {\n            const candidate = window.localStorage.getItem(key)\n            if (candidate === "light" || candidate === "dark") stored = candidate\n        } catch {\n            stored = null\n        }\n        theme = stored ?? (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light")\n        source = stored ? "user" : "system"\n    }\n\n    root.dataset.theme = theme\n    root.dataset.themeSource = source\n    root.style.colorScheme = theme\n    document.querySelector(\'meta[name="theme-color"]\')?.setAttribute("content", theme === "dark" ? "#151613" : "#f3f0e9")\n})()\n')
write('src/assets/icons/caret-down-dark.svg', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" aria-hidden="true">\n  <path fill="#f5f1e8" d="M213.66,101.66l-80,80a8,8,0,0,1-11.32,0l-80-80A8,8,0,0,1,53.66,90.34L128,164.69l74.34-74.35a8,8,0,0,1,11.32,11.32Z"/>\n</svg>\n')
write('electron/g08-theme-smoke.cjs', 'const crypto = require("node:crypto")\nconst fs = require("node:fs")\nconst path = require("node:path")\n\nconst THEME_KEY = "galileo-gallery-interface-theme-v1"\nconst PROJECT_KEY = "galileo-gallery-project-v1"\n\nconst CONTEXTS = {\n    catalogue: {\n        shell: ".style-gallery-shell",\n        strong: ".style-gallery-header h1",\n        muted: ".style-gallery-header p",\n        stable: [".style-gallery-header", ".style-gallery-tools", ".style-gallery-grid"],\n    },\n    studio: {\n        shell: ".app-shell",\n        strong: ".panel-heading h2",\n        muted: ".brand-lockup span",\n        stable: [".titlebar", ".library", ".studio", ".inspector"],\n    },\n}\n\nfunction sha256(value) {\n    return crypto.createHash("sha256").update(value).digest("hex")\n}\n\nasync function settle(window) {\n    await window.webContents.executeJavaScript(`(async () => {\n        await document.fonts.ready\n        await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => requestAnimationFrame(resolve))))\n        return true\n    })()`)\n}\n\nasync function capture(window, outputDirectory, name) {\n    await settle(window)\n    const image = await window.webContents.capturePage()\n    const png = image.toPNG()\n    const file = path.join(outputDirectory, `${name}.png`)\n    fs.writeFileSync(file, png)\n    return {\n        file: path.basename(file),\n        bytes: png.length,\n        sha256: sha256(png),\n        size: image.getSize(),\n    }\n}\n\nasync function reload(window) {\n    await new Promise((resolve, reject) => {\n        const timer = setTimeout(() => reject(new Error("Theme persistence reload timed out.")), 15_000)\n        window.webContents.once("did-finish-load", () => {\n            clearTimeout(timer)\n            resolve()\n        })\n        window.webContents.reload()\n    })\n    await settle(window)\n}\n\nasync function chooseTheme(window, target) {\n    const result = await window.webContents.executeJavaScript(`(async () => {\n        const target = ${JSON.stringify(target)}\n        const control = document.querySelector("[data-interface-theme-control]")\n        if (!control) throw new Error("Interface theme control is missing.")\n        const current = document.documentElement.dataset.theme\n        const stored = localStorage.getItem("galileo-gallery-interface-theme-v1")\n        const source = document.documentElement.dataset.themeSource\n        if (current === target && (stored !== target || source !== "user")) {\n            control.click()\n            await new Promise((resolve) => requestAnimationFrame(resolve))\n            control.click()\n        } else if (current !== target) {\n            control.click()\n        }\n        const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches\n        await new Promise((resolve) => setTimeout(resolve, reducedMotion ? 20 : 280))\n        await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))\n        return {\n            theme: document.documentElement.dataset.theme,\n            stored: localStorage.getItem(${JSON.stringify(THEME_KEY)}),\n        }\n    })()`)\n    if (result.theme !== target || result.stored !== target) {\n        throw new Error(`Theme control did not visibly persist ${target} mode: ${JSON.stringify(result)}`)\n    }\n    await settle(window)\n}\n\nasync function readThemeSnapshot(window, context) {\n    const config = CONTEXTS[context]\n    if (!config) throw new Error(`Unknown theme verification context: ${context}`)\n    return window.webContents.executeJavaScript(`(() => {\n        const config = ${JSON.stringify(config)}\n        const rect = (selector) => {\n            const element = document.querySelector(selector)\n            if (!element) throw new Error("Missing themed element: " + selector)\n            const box = element.getBoundingClientRect()\n            return { left: box.left, top: box.top, right: box.right, bottom: box.bottom, width: box.width, height: box.height }\n        }\n        const resolveColour = (value) => {\n            const probe = document.createElement("span")\n            probe.style.color = value\n            probe.style.position = "fixed"\n            probe.style.pointerEvents = "none"\n            document.body.appendChild(probe)\n            const resolved = getComputedStyle(probe).color\n            probe.remove()\n            return resolved\n        }\n        const parseColour = (value) => {\n            const numbers = value.match(/[\\d.]+/g)?.map(Number) ?? []\n            return { r: numbers[0] ?? 0, g: numbers[1] ?? 0, b: numbers[2] ?? 0 }\n        }\n        const luminance = (value) => {\n            const colour = parseColour(value)\n            const channel = (part) => {\n                const normal = part / 255\n                return normal <= .04045 ? normal / 12.92 : Math.pow((normal + .055) / 1.055, 2.4)\n            }\n            return .2126 * channel(colour.r) + .7152 * channel(colour.g) + .0722 * channel(colour.b)\n        }\n        const contrast = (a, b) => {\n            const first = luminance(a)\n            const second = luminance(b)\n            return (Math.max(first, second) + .05) / (Math.min(first, second) + .05)\n        }\n\n        const root = document.documentElement\n        const rootStyle = getComputedStyle(root)\n        const control = document.querySelector("[data-interface-theme-control]")\n        if (!control) throw new Error("Interface theme control is missing.")\n        const controlStyle = getComputedStyle(control)\n        const shell = document.querySelector(config.shell)\n        if (!shell) throw new Error("Theme shell is missing.")\n        const shellStyle = getComputedStyle(shell)\n        const controlBox = control.getBoundingClientRect()\n        control.focus()\n        const focusStyle = getComputedStyle(control)\n        const ink = resolveColour(rootStyle.getPropertyValue("--ink").trim())\n        const muted = resolveColour(rootStyle.getPropertyValue("--muted").trim())\n        const material = resolveColour(rootStyle.getPropertyValue("--material").trim())\n        const stored = localStorage.getItem(${JSON.stringify(THEME_KEY)})\n        const projectDocument = localStorage.getItem(${JSON.stringify(PROJECT_KEY)})\n        return {\n            theme: root.dataset.theme,\n            source: root.dataset.themeSource,\n            stored,\n            colourScheme: rootStyle.colorScheme,\n            metaThemeColour: document.querySelector(\'meta[name="theme-color"]\')?.getAttribute("content") ?? null,\n            control: {\n                label: control.getAttribute("aria-label"),\n                pressed: control.getAttribute("aria-pressed"),\n                icon: control.querySelector("[data-phosphor-icon]")?.getAttribute("data-phosphor-icon") ?? null,\n                width: controlBox.width,\n                height: controlBox.height,\n                outlineStyle: focusStyle.outlineStyle,\n                outlineWidth: focusStyle.outlineWidth,\n            },\n            colours: {\n                ink,\n                muted,\n                material,\n                strongContrast: contrast(ink, material),\n                mutedContrast: contrast(muted, material),\n                strongElement: getComputedStyle(document.querySelector(config.strong)).color,\n                mutedElement: getComputedStyle(document.querySelector(config.muted)).color,\n            },\n            caret: rootStyle.getPropertyValue("--pd-select-caret").trim(),\n            motion: {\n                reduced: matchMedia("(prefers-reduced-motion: reduce)").matches,\n                transitionDuration: shellStyle.transitionDuration,\n            },\n            shell: {\n                clientWidth: shell.clientWidth,\n                scrollWidth: shell.scrollWidth,\n                clientHeight: shell.clientHeight,\n                scrollHeight: shell.scrollHeight,\n            },\n            stable: Object.fromEntries(config.stable.map((selector) => [selector, rect(selector)])),\n            projectDocument,\n            projectContainsTheme: Boolean(projectDocument && (projectDocument.includes(${JSON.stringify(THEME_KEY)}) || projectDocument.includes(\'"interfaceTheme"\'))),\n        }\n    })()`)\n}\n\nfunction maxGeometryDelta(first, second) {\n    let maximum = 0\n    for (const selector of Object.keys(first)) {\n        const a = first[selector]\n        const b = second[selector]\n        for (const key of ["left", "top", "right", "bottom", "width", "height"]) {\n            maximum = Math.max(maximum, Math.abs(a[key] - b[key]))\n        }\n    }\n    return maximum\n}\n\nfunction assertThemeSnapshot(snapshot, mode, context) {\n    const next = mode === "dark" ? "light" : "dark"\n    const expectedIcon = next === "dark" ? "moon" : "sun"\n    if (snapshot.theme !== mode || snapshot.stored !== mode || snapshot.source !== "user") {\n        throw new Error(`${context} did not expose persisted ${mode} mode: ${JSON.stringify(snapshot)}`)\n    }\n    if (snapshot.colourScheme !== mode) throw new Error(`${context} did not expose ${mode} color-scheme.`)\n    const expectedThemeColour = mode === "dark" ? "#151613" : "#f3f0e9"\n    if (snapshot.metaThemeColour?.toLowerCase() !== expectedThemeColour) throw new Error(`${context} did not update the application theme colour for ${mode} mode.`)\n    if (snapshot.control.label !== `Switch to ${next} mode`\n        || snapshot.control.pressed !== String(mode === "dark")\n        || snapshot.control.icon !== expectedIcon) {\n        throw new Error(`${context} theme control does not truthfully describe ${mode} state.`)\n    }\n    if (snapshot.control.width < 44 || snapshot.control.height < 44) {\n        throw new Error(`${context} theme control is smaller than 44px.`)\n    }\n    if (snapshot.control.outlineStyle === "none" || parseFloat(snapshot.control.outlineWidth) < 2) {\n        throw new Error(`${context} theme control lacks visible keyboard focus.`)\n    }\n    if (snapshot.shell.scrollWidth > snapshot.shell.clientWidth + 1) {\n        throw new Error(`${context} ${mode} mode introduces horizontal clipping.`)\n    }\n    if (snapshot.colours.strongContrast < 7 || snapshot.colours.mutedContrast < 4.5) {\n        throw new Error(`${context} ${mode} palette misses interface contrast: ${JSON.stringify(snapshot.colours)}`)\n    }\n    if (snapshot.projectContainsTheme) {\n        throw new Error(`${context} leaked interface theme preference into Project data.`)\n    }\n    if (!snapshot.motion.reduced && snapshot.motion.transitionDuration.split(",").every((value) => parseFloat(value) < .15)) {\n        throw new Error(`${context} theme change has no restrained colour transition.`)\n    }\n}\n\nasync function verifySystemFallback(window, context) {\n    await window.webContents.executeJavaScript(`localStorage.removeItem(${JSON.stringify(THEME_KEY)})`)\n    await reload(window)\n    const expected = await window.webContents.executeJavaScript(`matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"`)\n    const snapshot = await readThemeSnapshot(window, context)\n    if (snapshot.theme !== expected || snapshot.source !== "system" || snapshot.stored !== null) {\n        throw new Error(`${context} did not follow the operating-system theme on first run: ${JSON.stringify(snapshot)}`)\n    }\n    return { expected, snapshot }\n}\n\nasync function verifyDarkProjectMenu(window, outputDirectory) {\n    const result = await window.webContents.executeJavaScript(`(async () => {\n        const trigger = document.querySelector(".project-trigger")\n        const panel = document.querySelector(".project-menu-panel")\n        if (!trigger || !panel) throw new Error("Project menu is missing in dark mode.")\n        const before = [".titlebar", ".library", ".studio", ".inspector"].map((selector) => {\n            const box = document.querySelector(selector).getBoundingClientRect()\n            return { left: box.left, top: box.top, right: box.right, bottom: box.bottom, width: box.width, height: box.height }\n        })\n        trigger.click()\n        const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches\n        await new Promise((resolve) => setTimeout(resolve, reduced ? 20 : 280))\n        const style = getComputedStyle(panel)\n        const box = panel.getBoundingClientRect()\n        return {\n            open: trigger.getAttribute("aria-expanded"),\n            hidden: panel.getAttribute("aria-hidden"),\n            opacity: Number(style.opacity),\n            colour: style.color,\n            background: style.backgroundColor,\n            insideViewport: box.left >= -1 && box.right <= innerWidth + 1 && box.top >= -1 && box.bottom <= innerHeight + 1,\n            before,\n        }\n    })()`)\n    if (result.open !== "true" || result.hidden !== "false" || result.opacity < .99 || !result.insideViewport) {\n        throw new Error(`Dark Project menu did not open cleanly: ${JSON.stringify(result)}`)\n    }\n    const screenshot = await capture(window, outputDirectory, "gallery-studio-dark-project-menu")\n    const close = await window.webContents.executeJavaScript(`(async () => {\n        window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }))\n        const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches\n        await new Promise((resolve) => setTimeout(resolve, reduced ? 20 : 360))\n        const after = [".titlebar", ".library", ".studio", ".inspector"].map((selector) => {\n            const box = document.querySelector(selector).getBoundingClientRect()\n            return { left: box.left, top: box.top, right: box.right, bottom: box.bottom, width: box.width, height: box.height }\n        })\n        return {\n            expanded: document.querySelector(".project-trigger").getAttribute("aria-expanded"),\n            hidden: document.querySelector(".project-menu-panel").getAttribute("aria-hidden"),\n            after,\n        }\n    })()`)\n    const maximumLayoutShift = Math.max(...result.before.flatMap((box, index) =>\n        ["left", "top", "right", "bottom", "width", "height"].map((key) => Math.abs(box[key] - close.after[index][key]))\n    ))\n    if (close.expanded !== "false" || close.hidden !== "true" || maximumLayoutShift > .75) {\n        throw new Error(`Dark Project menu did not close without layout shift: ${JSON.stringify({ close, maximumLayoutShift })}`)\n    }\n    await settle(window)\n    return { ...result, maximumLayoutShift, screenshot }\n}\n\nasync function verifyThemeModes(window, outputDirectory, context, options = {}) {\n    fs.mkdirSync(outputDirectory, { recursive: true })\n    const projectBefore = await window.webContents.executeJavaScript(`localStorage.getItem(${JSON.stringify(PROJECT_KEY)})`)\n    const system = options.verifySystem ? await verifySystemFallback(window, context) : null\n\n    await chooseTheme(window, "light")\n    const light = await readThemeSnapshot(window, context)\n    assertThemeSnapshot(light, "light", context)\n    const captures = {\n        [`theme-${context}-light`]: await capture(window, outputDirectory, `gallery-${context}-light`),\n    }\n\n    await chooseTheme(window, "dark")\n    const dark = await readThemeSnapshot(window, context)\n    assertThemeSnapshot(dark, "dark", context)\n    captures[`theme-${context}-dark`] = await capture(window, outputDirectory, `gallery-${context}-dark`)\n\n    const maximumLayoutShift = maxGeometryDelta(light.stable, dark.stable)\n    if (maximumLayoutShift > .75) {\n        throw new Error(`${context} theme switch changes interface geometry by ${maximumLayoutShift}px.`)\n    }\n    if (light.caret === dark.caret) throw new Error(`${context} did not switch to a light-on-dark select caret.`)\n    if (light.colours.ink === dark.colours.ink || light.colours.material === dark.colours.material) {\n        throw new Error(`${context} light and dark palettes are not materially distinct.`)\n    }\n    if (projectBefore !== dark.projectDocument) {\n        throw new Error(`${context} theme switching changed Project state.`)\n    }\n\n    const darkProjectMenu = context === "studio"\n        ? await verifyDarkProjectMenu(window, outputDirectory)\n        : null\n    if (darkProjectMenu) captures["theme-studio-dark-project-menu"] = darkProjectMenu.screenshot\n\n    let persistence = null\n    if (options.verifyPersistence) {\n        await reload(window)\n        const persisted = await readThemeSnapshot(window, context)\n        assertThemeSnapshot(persisted, "dark", `${context} reload`)\n        persistence = { theme: persisted.theme, source: persisted.source, stored: persisted.stored }\n    }\n\n    await window.webContents.executeJavaScript(`(() => {\n        const text = "light"\n        localStorage.setItem(${JSON.stringify(THEME_KEY)}, text)\n        window.dispatchEvent(new StorageEvent("storage", {\n            key: ${JSON.stringify(THEME_KEY)},\n            newValue: text,\n            storageArea: localStorage,\n        }))\n    })()`)\n    await new Promise((resolve) => setTimeout(resolve, 60))\n    const storageSync = await readThemeSnapshot(window, context)\n    assertThemeSnapshot(storageSync, "light", `${context} storage sync`)\n\n    const projectAfter = await window.webContents.executeJavaScript(`localStorage.getItem(${JSON.stringify(PROJECT_KEY)})`)\n    if (projectBefore !== projectAfter) throw new Error(`${context} theme verification changed Project state.`)\n\n    return {\n        context,\n        system,\n        persistence,\n        storageSync: {\n            theme: storageSync.theme,\n            source: storageSync.source,\n            stored: storageSync.stored,\n        },\n        maximumLayoutShift,\n        light,\n        dark,\n        darkProjectMenu,\n        captures,\n    }\n}\n\nmodule.exports = { verifyThemeModes }\n')
write('docs/releases/v1.2.0.md', '# Galileo Gallery 1.2.0\n\nA complete interface-colour release. Scene engines, media, Project data, Timeline behaviour, and deterministic export remain unchanged.\n\n## Added\n\n- A native-feeling Light / Dark control in both the Scene catalogue and studio.\n- First-run operating-system preference, local persistence, cross-window storage synchronisation, and matching application theme colour.\n- Dedicated warm dark palette rather than colour inversion.\n- Separate Phosphor-derived select carets for light and dark surfaces.\n- Forced-colour, increased-contrast, reduced-transparency, and reduced-motion fallbacks.\n\n## Hardened\n\n- Theme changes preserve titlebar, panel, stage, card, and action geometry with no layout shift.\n- Theme preference remains local interface state and never enters `.galileo` Projects, Scene settings, Timeline state, or export requests.\n- Hidden export renderers use the neutral existing colour boundary rather than a user-interface preference.\n- G08 now verifies both modes, system fallback, persisted reload, storage synchronisation, contrast, focus visibility, menu treatment, clipping, and Project invariance.\n- Production dependencies are audited separately from development-tool transitive dependencies before packaging.\n\n## Source anchors\n\n- pitch.dog type system: `bomkino/pitchdog-type-system@786b4a2b671182319320f922b8de8f927ea3a002`\n- Phosphor React: `@phosphor-icons/react@2.1.10`\n')

